{"cards": [{"node_code": "N_f43ec1abee00b97d", "definition": "研究隧道开挖前后围岩及周围山体岩层在应力重分布作用下产生的位移、变形及破坏规律的观测与试验技术。", "boundary": "本节点聚焦于“岩层”本身的运动状态。边界在于区分“岩层移动”与“结构变形”（前者关注围岩介质，后者关注衬砌结构）、“岩层移动”与“山体压力”（前者关注位移量，后者关注力的大小）。若内容涉及岩层移动对结构的影响分析，侧重观测数据归本节点，侧重力学机理归结构理论。", "includes": ["围岩收敛、沉降及水平位移观测技术", "岩层破裂、滑移及塑性区扩展的监测方法", "基于岩层移动数据的稳定性评估"], "excludes": ["隧道衬砌结构的变形监测", "山体压力（应力）的测量技术"], "sibling_distinctions": [{"other_code": "N_06b98247e0d05130", "rule": "岩层移动关注位移与变形（运动学），山体压力关注应力与荷载（静力学/动力学）。"}, {"other_code": "N_adf73da387ea26bb", "rule": "岩层移动是监测的具体对象之一，隧道施工及运用监测涵盖更广泛的监测体系（含结构、环境等）。"}], "cross_boundary_rule": "若内容同时包含岩层移动与山体压力数据，侧重位移分析归本节点，侧重应力分析归山体压力；若为综合监测方案，可关联隧道施工及运用监测。"}, {"node_code": "N_06b98247e0d05130", "definition": "研究隧道工程中对围岩及山体内部应力状态、荷载分布进行测量、反演及分析的观测与试验技术。", "boundary": "本节点聚焦于“力”的测量与分析。边界在于区分“山体压力”与“岩层移动”（前者关注应力/力，后者关注位移/变形）、“山体压力”与“结构内力”（前者关注外部荷载，后者关注结构响应）。若内容涉及压力传感器布置及数据解读，归本节点；若涉及基于压力数据的支护设计，归结构理论或施工。", "includes": ["围岩应力、地压及荷载的测量技术", "压力传感器、测力计等设备的选用与安装", "山体压力分布规律及变化趋势分析"], "excludes": ["岩层位移与变形监测", "隧道衬砌结构内力监测"], "sibling_distinctions": [{"other_code": "N_f43ec1abee00b97d", "rule": "山体压力关注应力与荷载（力），岩层移动关注位移与变形（运动）。"}, {"other_code": "N_adf73da387ea26bb", "rule": "山体压力是监测的具体对象之一，隧道施工及运用监测涵盖更广泛的监测体系。"}], "cross_boundary_rule": "若内容涉及“应力-应变”耦合分析，侧重应力测量归本节点，侧重应变/位移测量归岩层移动；若为综合监测，可关联隧道施工及运用监测。"}, {"node_code": "N_adf73da387ea26bb", "definition": "研究隧道在施工建造及运营维护全生命周期中，对结构安全、环境参数及施工状态进行系统性监测与评估的技术体系。", "boundary": "本节点聚焦于“监测体系”与“全过程管理”。边界在于区分“监测”与“单一对象观测”（本节点涵盖结构、环境、施工状态等综合监测，兄弟节点侧重特定物理量）、“监测”与“养护”（监测提供数据，养护基于数据采取行动）。若内容涉及监测系统设计、数据集成及预警机制，归本节点。", "includes": ["隧道施工期及运营期综合监测方案与设计", "结构变形、应力、渗水、通风等环境参数监测", "监测数据集成、分析及安全预警系统"], "excludes": ["单一物理量（如仅岩层移动或仅山体压力）的测量原理", "基于监测结果的结构加固或维修工艺"], "sibling_distinctions": [{"other_code": "N_f43ec1abee00b97d", "rule": "隧道施工及运用监测是综合体系，岩层移动是其中监测的具体对象之一。"}, {"other_code": "N_06b98247e0d05130", "rule": "隧道施工及运用监测是综合体系，山体压力是其中监测的具体对象之一。"}], "cross_boundary_rule": "若内容涉及特定物理量（如岩层移动）的监测技术，主挂载对应兄弟节点；若涉及整体监测流程、系统集成或综合评估，主挂载本节点。"}]}
